navjs='''// native details works even before JavaScript loads.
const menu=document.querySelector('#site-menu');
const trigger=menu.querySelector('summary');
trigger.setAttribute('aria-expanded',String(menu.open));
trigger.addEventListener('click',event=>{event.preventDefault();menu.open=!menu.open;trigger.setAttribute('aria-expanded',String(menu.open));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.open){menu.open=false;trigger.setAttribute('aria-expanded','false');trigger.focus();}});
document.addEventListener('click',event=>{if(!menu.contains(event.target)){menu.open=false;trigger.setAttribute('aria-expanded','false');}});'''
validation='''document.querySelector('#request-form').addEventListener('submit',event=>{
 event.preventDefault();const form=event.currentTarget;const status=document.querySelector('#form-status');
 const name=form.elements.namedItem('name').value.trim();
 const email=form.elements.namedItem('email').value.trim();
 const message=form.elements.namedItem('message').value.trim();
 if(name.length<2||message.length<10||!form.checkValidity()){status.textContent='შეავსე სახელი, სწორი ელფოსტა და მინიმუმ 10-სიმბოლოიანი შეტყობინება.';return;}
 status.textContent='დემო მზადაა: '+name+', მონაცემები შემოწმებულია. შეტყობინება არ გაგზავნილა.';
});'''
