def delta(before,after):
 start=0
 while start<min(len(before),len(after)) and before[start]==after[start]:start+=1
 end=0
 while end<min(len(before)-start,len(after)-start) and before[len(before)-end-1]==after[len(after)-end-1]:end+=1
 removed=before[start:len(before)-end if end else len(before)]
 insert=after[start:len(after)-end if end else len(after)]
 return dict(at=len(before[:start].encode('utf-16-le'))//2,remove=len(removed.encode('utf-16-le'))//2,insert=insert)
compact=[]
for project in projects:
 record={key:value for key,value in project.items() if key not in ['stages','preview']};record['stages']=[]
 previous=project['stages'][0]['starter']
 for stage in project['stages']:
  entry={key:value for key,value in stage.items() if key not in ['starter','solution']}
  entry['patches']={lang:delta(previous[lang],stage['solution'][lang]) for lang in ['html','css','js'] if previous[lang]!=stage['solution'][lang]}
  if stage['id']==1 or stage.get('resetStarter'):entry['starter']=stage['starter']
  record['stages'].append(entry);previous=stage['solution']
 compact.append(record)
header="""import type { CodeFiles, Check, Progress } from './types';
import { photos } from './photos.ts';
export type StudioStage = { id:number; title:string; concept:string; explanation:string; task:string; snippet:string; hints:string[]; checks:Check[]; review:string[]; starter:CodeFiles; solution:CodeFiles; transfer:boolean; resetStarter?:boolean };
export type StudioProject = { id:string; title:string; subtitle:string; kind:string; level:number; minutes:number; skills:string[]; lessons:number[]; accent:string; paper:string; ink:string; brief:string; audience:string; reuse:string; preview:CodeFiles; stages:StudioStage[] };
type Patch={at:number;remove:number;insert:string};
type StageSpec=Omit<StudioStage,'starter'|'solution'>&{starter?:CodeFiles;patches:Partial<Record<keyof CodeFiles,Patch>>};
type ProjectSpec=Omit<StudioProject,'stages'|'preview'>&{stages:StageSpec[]};
// Generated by scripts/authoring/studio_v2.py. Deltas avoid shipping repeated full files.
const authored:ProjectSpec[] = """
helper=""";
function creditFiles(files:CodeFiles):CodeFiles{
 const used=photos.filter(photo=>Object.values(files).some(code=>code.includes(photo.path)));
 const credits=used.map(photo=>`<p><a href="${photo.source}" target="_blank" rel="noreferrer">${photo.credit}</a> / <a href="${photo.licenseUrl}" target="_blank" rel="noreferrer">${photo.license}</a></p>`).join('');
 return {...files,html:files.html.replace('<!-- PHOTO_CREDITS -->',credits)};
}
export const studioProjects:StudioProject[]=authored.map(project=>{
 let files:CodeFiles={html:'',css:'',js:''};
 const stages:StudioStage[]=project.stages.map(spec=>{
  if(spec.id===1)files={...spec.starter!};
  const starter=creditFiles(spec.starter??files);const solution={...files};
  for(const language of ['html','css','js'] as const){const patch=spec.patches[language];if(patch)solution[language]=files[language].slice(0,patch.at)+patch.insert+files[language].slice(patch.at+patch.remove);}
  files=solution;const {patches,...stage}=spec;void patches;
  return {...stage,starter,solution:creditFiles(solution)};
 });
 return {...project,stages,preview:stages[16].solution};
});
export const studioTotal=studioProjects.reduce((sum,project)=>sum+project.stages.length,0);
export const stageKey=(project:string,stage:number)=>`${project}:v2:${stage}`;
export function studioCanOpen(project:string,stage:number,p:Progress){const found=studioProjects.find(item=>item.id===project);return !!found&&Number.isInteger(stage)&&stage>=1&&stage<=found.stages.length&&(stage===1||!!p.studio?.completed.includes(stageKey(project,stage-1)));}
export function studioCount(p:Progress){return studioProjects.reduce((sum,project)=>sum+project.stages.filter(stage=>p.studio?.completed.includes(stageKey(project.id,stage.id))).length,0);}
export function studioNext(p:Progress){const recent=p.studio?.completed.at(-1)?.split(':')[0];const ordered=[...studioProjects].sort((a,b)=>Number(b.id===recent)-Number(a.id===recent));for(const project of ordered)for(const stage of project.stages)if(!p.studio?.completed.includes(stageKey(project.id,stage.id)))return {project,stage};return null;}
export function studioDocument(files:CodeFiles){return `<!doctype html><html lang="ka"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data: https: http:; script-src 'none'"><style>${files.css.replace(/<\\/style/gi,'<\\\\/style')}</style></head><body>${files.html}</body></html>`;}
"""
(ROOT/'lib/academy/studio.ts').write_text(header+json.dumps(compact,ensure_ascii=False,indent=2)+helper)
print(f'Authored {len(projects)} projects / {sum(len(p["stages"]) for p in projects)} stages with compact deltas')
